\label{def_split}
Let $B$ be a unital associative algebra over $\mathbb{C}$. We say that $B$ is a \emph{split $C^*$-by-nilpotent} algebra if the following conditions hold:
\begin{enumerate}[(a)]
\item $B$ has a unital subalgebra $\mathcal{A}$ that is a $C^*$-algebra and $1_\ensuremath{\mathcal{A}}=1_B$.
\item $B$ has an ideal $N$ which consists of nilpotent elements;
\item $B=\ensuremath{\mathcal{A}} + N$; \label{direct sum}
\item The elements of $\mathcal{A}$ and $N$ commute.
\end{enumerate}

\label{remsplit}{\ }
\begin{enumerate}[(i)]
\item $\ensuremath{\mathcal{A}} \cap N =0$, since $\ensuremath{\mathcal{A}} \cap N$ is a commutative $C^*$-algebra consisting of nilpotent elements. Thus, $B=\ensuremath{\mathcal{A}} \oplus N$ as vector spaces.
\item $\ensuremath{\mathcal{A}} \cong B/N$ as associative algebras: indeed, the map $\pi_1 \colon b=a+n \mapsto a$ defines a unital associative algebra epimorphism $B \to \ensuremath{\mathcal{A}}$ with kernel $N$.
\item The diagram
\begin{equation*}\label{diag:SplV}
\begin{tikzcd}
N \arrow[r, "i"]
&B \arrow[r, shift left, "\pi_1"]
&\ensuremath{\mathcal{A}} \arrow[l, shift left, "j"]
\end{tikzcd}
\end{equation*}
where $i$ and $j$ are the canonical inclusions, is a split extension in the variety of associative algebras. Indeed, as shown above, $\pi_1$ is an epimorphism with kernel $N$. Moreover, since $\ensuremath{\mathcal{A}}$ is a subalgebra of $B$, the inclusion $j$ is a homomorphism of associative algebras such that $\pi_1\circ j=\operatorname{id}_{\ensuremath{\mathcal{A}}}$.
\item $N$ is the \emph{Jacobson radical} $\operatorname{rad}(B)$ of $B$. Indeed, $N\subseteq \operatorname{rad}(B)$ and $\operatorname{rad}(\mathcal{A})=0$ (see~\cite[Corollary 3.2.13]{Dales}).
\item The decomposition $B=\ensuremath{\mathcal{A}} \oplus N$ is unique: if $B=\ensuremath{\mathcal{A}} \oplus N = \ensuremath{\mathcal{A}}' \oplus N'$, then $N=\operatorname{rad}(B)=N'$ and $\ensuremath{\mathcal{A}} \cong B/N =B/ \operatorname{rad}(B) =B/N' \cong \ensuremath{\mathcal{A}}'$ as associative algebras. Thus, the $C^*$-algebra structure of $\ensuremath{\mathcal{A}}$ is uniquely determined.
\end{enumerate}

Consider the split $C^*$-by-nilpotent algebra
\[
B_3=
\left\{
\begin{pmatrix}
a & c_1 & c_2 \\
0 & a & c_3 \\
0 & 0 & a
\end{pmatrix}
\; \Bigg\vert \; a,c_1,c_2,c_3\in \mathbb{C}
\right\}.
\]
One may check that
\[
B_3^+=\left\{
\begin{pmatrix}
a & c_1 & c_2\\
0 & a & c_3\\
0 & 0 & a
\end{pmatrix}
\; \Bigg\vert \;
a \in \mathbb{R}^+ \cup \{0\}, \ c_1,c_2,c_3 \in \mathbb{C} \right\},
\]
while
\[
B_3^{++}=\left\{
\begin{pmatrix}
a & c_1 & c_2\\
0 & a & c_3\\
0 & 0 & a
\end{pmatrix}
\; \Bigg\vert \;
a \in \mathbb{R}^+, \ c_1,c_2,c_3 \in \mathbb{C}
\right\}
\]
is the set of matrices \eqref{eq:upper-triangular}. Finally, the set of invertible elements of $B_3$ is
\[
1+N=\left\{
\begin{pmatrix}
a & c_1 & c_2\\
0 & a & c_3\\
0 & 0 & a
\end{pmatrix}
\; \Bigg\vert \;
a,c_1,c_2,c_3 \in \mathbb{C}, \ a \neq 0
\right\}.
\]

~\cite{MR1741419}
A \emph{semi-norm} on a $\mathbb{C}$-vector space $V$ is a function $p \colon V \to \mathbb{R}$ such that 
\begin{enumerate}[(a)]
\item $p(x+y) \leq p(x)+p(y)$;
\item $p(\lambda x) = |\lambda| p(x)$;
\end{enumerate}
for any $x,y\in V$ and $\lambda \in \mathbb{C}$.

It follows easily from \Cref{lm:sqrtB+} that the operations \eqref{eq:circdef}, \eqref{eq:sharpdef}, and \eqref{eq:stardef} are well-defined on $B^{++}$. It remains to show that $x \circ y = y \circ x$, for any $x,y \in B^{++}$.

Since $B^{++}$ is a $2$-divisible twisted subgroup of the group of units $1+N$, and
\begin{align} \label{eq:circbysharp}
x\circ y =x+y+x(x^{-1}\# y) +(x^{-1}\# y)x,
\end{align}
with
\begin{align} \label{8++}
(x(x^{-1}\# y))^2=xy, \quad ((x^{-1}\# y)x)^2=yx,
\end{align}
holds, it follows that \eqref{eq:circdef} is commutative on $B^{++}$.

As a direct consequence of \Cref{lm:lts}, one may easily see that the following are equivalent.
\begin{enumerate}[(i)]
\item The identity $[[x,y],z]=0$ holds in $B$;
\item The identity $[[x,y],y]-[[y,x],x]=0$ holds in $B^{++}$;
\item There exists $\varepsilon >0$ such that $[[x,y],y]-[[y,x],x]=0$ holds for any $x,y\in B^{++}$ with $\|x\|_s< \varepsilon$, $\|y\|_s<\varepsilon$.
\end{enumerate}

One may check that, in any ring, the identities
\begin{align}\label{eq:pr:lts_1}
ab^2a-ba^2b = [[a,b],b]a-b[[b,a],a]
\end{align}
and
\begin{align}\label{eq:pr:lts_2}
a^2b^2a^2 - (aba)^2 = a(ab^2a-ba^2b)a
\end{align}
hold. By \Cref{lm:lts} the identity $[[x,y],z]=0$ holds for any $x,y,z\in B^{++}$, since we assumed $[[x,y],y]-[[y,x],x]=0$. This implies that equation \eqref{eq:pr:lts_1} becomes $ab^2a-ba^2b=0$, hence \eqref{eq:pr:lts_2} leads to $\sqrt{xyx}=\sqrt{x}\sqrt{y}\sqrt{x}$. Thus,
\begin{align*}
x\circ y &= \frac{1}{\sqrt{x}}\left(x+x^\frac{1}{4}y^\frac{1}{2}x^\frac{1}{4}\right)^2\frac{1}{\sqrt{x}} \\
&=  \left(x^{-\frac{1}{4}}\left(x+x^\frac{1}{4}y^\frac{1}{2}x^\frac{1}{4}\right)x^{-\frac{1}{4}}\right)^2 \\
&= (\sqrt{x}+\sqrt{y})^2, \qedhere
\end{align*}
where the second equality follows from $a^2b^2a^2-(aba)^2=0$ and the third one follows by straightforward computations.

\label{lm:prodrule}
There exists $\varepsilon>0$ such that for any $c,d>0$ and $x,y\in B$ with $\|x\|_s<c\varepsilon$, $\|y\|_s<d\varepsilon$, we have
\begin{equation} \label{eq:prodrule}
(c+x)\circ (d+y) = (\sqrt{c}+\sqrt{d})^2+(\sqrt{c}+\sqrt{d})\left(\frac{x}{\sqrt{c}}+\frac{y}{\sqrt{d}}\right) + \sqrt{cd} \, \hat{s}\left(\frac{x}{c},\frac{y}{d}\right)
\end{equation}
and
\begin{equation}\label{eq_lemma5.1}
\|(c+x)\circ (d+y) - (\sqrt{c}+\sqrt{d})^2\|_s\leq 3(\sqrt{c}+\sqrt{d})^2\varepsilon.
\end{equation}

\label{lm:shatlow}
The low degree terms of the formal power series $\hat{s}(\xi,\eta)$ are given by
\begin{equation} \label{eq:shat_terms}
\hat{s}(\xi,\eta)=-\frac{1}{4}(\xi-\eta)^2+\frac{1}{8}(\xi^3-\xi\eta\xi-\eta\xi\eta+\eta^3) +O(4),
\end{equation}  
where $O(4)$ is for a formal sum of monomials of degree at least $4$ in the non-commuting variables $\xi, \eta$.

One may check that
\begin{multline*}
s(\xi+\eta+\xi\eta)=1+\frac{1}{2}\,(\xi+\eta)-\frac{1}{8}\,(\xi^2-3\xi\eta+\eta\xi+\eta^2)+ \\ \frac{1}{16}\,
(\xi^3-\xi^2\eta-\xi\eta\xi-\xi\eta^2+\eta\xi^2-\eta\xi\eta+\eta^2\xi+\eta^3) +O(4)
\end{multline*}
and then
\begin{multline*} \label{eq:s_sym_terms}
s(\xi+\eta+\xi\eta)+s(\xi+\eta+\eta\xi)= \\
2+\xi+\eta-\frac{1}{4}\,(\xi-\eta)^2 + \frac{1}{8}\,
(\xi^3-\xi\eta\xi-\eta\xi\eta+\eta^3) +O(4),
\end{multline*}
which implies \eqref{eq:shat_terms}.

\label{pr:Axy_expansion}
Let $B=\mathcal{A}\oplus N$ be a split $C^*$-by-nilpotent algebra. There exists $\varepsilon>0$ such that, for any $x,y\in B$ with $\|x\|_s< \varepsilon$ and $\|y\|_s<\varepsilon$, the low degree terms of $A(x,y)$ are given by
\begin{align*}
A(x,y) = \dfrac{1}{32}([[x,y],y]-[[y,x],x]) + O(4).
\end{align*}
